"""Print every instrument's parameters as Markdown tables (the README's instrument reference is generated by this).

    python -m filmsynth.instruments            # all instruments
    python -m filmsynth.instruments Pluck Bell # some
"""
import sys

from . import ALL


def table(cls) -> str:
    doc = (cls.__doc__ or "").strip().split("\n\n")[0].replace("\n", " ")
    lines = [f"#### `{cls.__name__}`", "", " ".join(doc.split()), "", "| 参数 | 默认 | 说明 |", "|---|---|---|"]
    for k, (d, txt) in cls.PARAMS.items():
        lines.append(f"| `{k}` | `{d!r}` | {txt.replace('|', '/')} |")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    names = set(sys.argv[1:])
    print("\n".join(table(c) for c in ALL if not names or c.__name__ in names))
